                m_awready_r <= 1'b0;
                m_awreq_r   <= 1'b1;
            end else if (m_axil_awready && m_awvalid_r) begin
                m_awvalid_r <= 1'b0;
                m_awready_r <= 1'b1;
                m_awack_r   <= 1'b1;
            end else if (m_awack_r) begin
