            m_wstrb_r  <= {STRB_WIDTH{1'b0}};
            m_wvalid_r <= 1'b0;
            m_wready_r <= 1'b0;
            m_wreq_r   <= 1'b0;
            m_wack_r   <= 1'b0;
        end else begin
            if (s_w_to_m_req && !m_wreq_r) begin
                m_wdata_r  <= s_wdata_r;
                m_wstrb_r  <= s_wstrb_r;
                m_wvalid_r <= 1'b1;
                m_wready_r <= 1'b0;
                m_wreq_r   <= 1'b1;
            end else if (m_axil_wready && m_wvalid_r) begin
                m_wvalid_r <= 1'b0;
                m_wready_r <= 1'b1;
                m_wack_r   <= 1'b1;
            end else if (m_wack_r) begin
                m_wack_r   <= 1'b0;
                m_wreq_r   <= 1'b0;
            end
        end
    end

