                m_breq_r   <= 1'b0;
                m_bvalid_r <= 1'b0;
                m_bready_r <= 1'b1;
            end
        end
    end

    // B channel: Slave side
    assign s_axil_bresp  = s_bresp_r;
    assign s_axil_bvalid = s_bvalid_r;
    assign s_b_to_m_req  = s_breq_r;
